 function defaults({sourceRatio,aspect,framing='wide',camera='static',source='reference',sourceKey}){const scale={wide:1,medium:.65,closeup:.4,detail:.24,reverse:1}[framing]||1,start=fit(sourceRatio,aspect,scale),motion=camera!=='static';let end={...start};if(camera==='push')end=zoom(start,.75,sourceRatio,aspect);else if(camera==='pull')end=zoom(start,1.4,sourceRatio,aspect);else if(camera==='pan'||camera==='track')end=move(start,.16,0);return {version:1,enabled:true,motion,source,sourceKey,sourceRatio,aspect,start,end,focus:centre(start)};}
 function status(project,shot){const plan=shot.composition;if(!plan?.enabled)return {active:false,reason:''};const image=plan.source==='result'?shot.result:project.reference;if(!image)return {active:false,reason:'image'};if(plan.sourceKey!==imageKey(image))return {active:false,reason:'image'};if(plan.aspect!==project.aspect)return {active:false,reason:'aspect'};return {active:true,reason:'',plan,image};}
